void sort_real(INTEGER n, REAL *x){ for(INTEGER i=0;i<n;i++) for(INTEGER j=i+1;j<n;j++) if(x[j]<x[i]){ REAL t=x[i]; x[i]=x[j]; x[j]=t; } }
int main(){ INTEGER n=20,lda=n,ldv=1,info,lwork=-1; REAL *coef=new REAL[n+1]; for(INTEGER i=0;i<=n;i++) coef[i]=0; coef[0]=1; for(INTEGER k=1;k<=n;k++){ for(INTEGER j=k;j>=1;j--) coef[j]=coef[j]-REAL(k)*coef[j-1]; } REAL *a=new REAL[n*n]; for(INTEGER i=0;i<n*n;i++) a[i]=0; for(INTEGER i=1;i<n;i++) a[i+(i-1)*lda]=1; for(INTEGER j=0;j<n;j++) a[j+(n-1)*lda]=-coef[n-j]/coef[0]; REAL *wr=new REAL[n]; REAL *wi=new REAL[n]; REAL *vl=new REAL[1]; REAL *vr=new REAL[1]; REAL wk; Rgeev("N","N",n,a,lda,wr,wi,vl,ldv,vr,ldv,&wk,lwork,info); lwork=castInTEGER(wk); REAL *work=new REAL[lwork]; Rgeev("N","N",n,a,lda,wr,wi,vl,ldv,vr,ldv,work,lwork,info); sort_real(n,wr); REAL maxerr=0; for(INTEGER i=0;i<n;i++){ REAL err=abs(wr[i]-REAL(i+1)); if(maxerr<err) maxerr=err; printf("root[%ld] = ",(long)i); printnum(wr[i]); printf(", error = "); printnum(err); printf("\n"); } printf("max root error = "); printnum(maxerr); printf("\n"); delete[] work; delete[] vr; delete[] vl; delete[] wi; delete[] wr; delete[] a; delete[] coef; return info!=0?1:0; }
